-- =====================================================================
-- «استمارة دعم وتطوير الهيئة التعليمية» وفق «نموذج تقييم أداء معلم» المعتمد.
--
-- • 11 عنصرًا بأوزانها المعتمدة (المجموع 85٪)، ولكل عنصر تفسيره وسلّم تقدير
--   من خمسة مستويات موصوفة، ومجالات التطوير يكتبها الزائر.
-- • قسمان لسير العمل: «أعمال داخل الصف» أثناء الزيارة (العناصر 4–9 = 50٪)،
--   و«أعمال إدارية ومكتبية» بعد الاطلاع على الملف (1–3 و10–11 = 35٪).
--   وتُطبع العناصر بترقيم النموذج المعتمد من 1 إلى 11.
-- • الجدولان القديمان (rb_class وrb_admin) يبقيان مخفيين في الإصدار (legacy)،
--   فتُطبع الاستمارات السابقة بشكلها كما صدرت.
--
-- يُنفَّذ مرة واحدة في Supabase ← SQL Editor، وتكرار التنفيذ آمن.
-- =====================================================================

with base as (
  select fields from public.form_templates where id = '767d1060-fb69-4888-8e64-32d787802bd5'
),
els as (
  select case when t.f->>'name' in ('rb_class', 'rb_admin') then t.f || '{"legacy": true}'::jsonb else t.f end as f, t.o
  from base, jsonb_array_elements(base.fields) with ordinality as t(f, o)
  where t.f->>'name' not in ('rb_perf_class', 'rb_perf_admin')
),
pos as (
  select coalesce((select o from els where f->>'name' = 'f4'), (select max(o) from els), 0) as p
),
added as (
  select '{"name": "rb_perf_class", "type": "rubric", "label": "أعمال داخل الصف", "required": false, "style": "official", "note": "سيتم التقييم أثناء الملاحظة الصفية.", "items": [{"no": 4, "title": "التنوع في استراتيجيات التدريس", "weight": 10, "text": "ويقصد بها قدرة المعلم على استخدام أساليب وطرائق تدريس مناسبة لتعزيز عملية التعلم. ويكون قادرًا على:", "bullets": ["استخدام استراتيجيات تدريس مناسبة للموقف التعليمي.", "استخدام استراتيجيات تدريس مناسبة لحاجات وميول المتعلمين.", "استخدام استراتيجيات تعمل على تنمية القدرة على التفكير والإبداع.", "استخدام استراتيجيات تنمي مهارات الحوار والمناقشة."], "levels": ["يعتمد فقط على طرق التدريس التقليدية والمباشرة مثل الشرح النظري دون إشراك المتعلمين.", "يستخدم استراتيجيات تدريس تقليدية، مع استخدام محدود لبعض الطرق الحديثة للأنشطة التعليمية التي لا تتناسب مع أهداف التدريس.", "يستخدم استراتيجيات تدريس مناسبة ومتنوعة وفعالة بشكل غير منتظم، وقد يواجه صعوبة في التطبيق الفعال.", "يُظهر استعدادًا لتجربة استراتيجيات تدريس جديدة مناسبة وفعالة، تتناسب مع أهداف الدرس واحتياجات المتعلمين، يستخدم مجموعة متوازنة من الأنشطة التعليمية التي تشمل التعلم التفاعلي، التعليم التعاوني، والمشاريع العملية. ويستخدمها بشكل فعال لتحفيز المتعلمين على المشاركة والتعلم.", "يُظهر مهارة استثنائية في الجمع بين الشرح النظري والتطبيق العملي، مما يحفز المتعلمين ويُشركهم بفاعلية في عملية التعلم. ويكيّف استراتيجيات التدريس بشكل فردي بناءً على احتياجات كل طالب، مما يضمن تحسين مستوى التعلم الشخصي."]}, {"no": 5, "title": "تحسين نتائج المتعلمين", "weight": 10, "text": "عملية تحسين التحصيل الدراسي تهدف إلى معالجة نقاط الضعف وتطوير نقاط القوة في أداء المتعلمين الأكاديمي وتنمية مهاراتهم. تشمل:", "bullets": ["تحديد أهداف ومعايير واضحة ليعرف المتعلمون ما يُتوقع منهم تحقيقه.", "تقديم إفادة سريعة ومحددة فور ملاحظة الأداء، مع التركيز على الإيجابيات وتقديم اقتراحات بناءة للتحسين.", "تكييف الإفادة وفق الاحتياجات الفردية لضمان التفاعل الفعّال وتشجيع المتعلمين على طرح الأسئلة وتطبيق الاقتراحات.", "تعزيز الثقة وتشجيع التطور من خلال تقديم ملاحظات تشجيعية وفرص لتحسين الأداء.", "استخدام التكنولوجيا لتقديم الإفادة بطرق مبتكرة مثل البريد الإلكتروني ومنصات التعلم."], "levels": ["نادرًا ما يوفر أي دعم للمتعلمين الذين يواجهون صعوبات في الأداء.", "يوفر بعض الدعم للمتعلمين، لكنه غير كافٍ لتحسين أدائهم بشكل ملموس.", "يُقدم دعمًا إضافيًا للمتعلمين ذوي الأداء الضعيف، يضع أهدافًا لتحسين النتائج، لكن المتابعة والتقييم غير منتظمة وتحتاج إلى تحسين في استهداف الاحتياجات الفردية.", "يُقدم دعمًا مخصصًا للمتعلمين ويستخدم استراتيجيات فعالة لمعالجة نقاط القصور وتعزيز نقاط القوة، ويضع أهدافًا واضحة لتحسين نتائج المتعلمين ويتابع تقدمهم بانتظام ويُجري تعديلات على الخطط عند الحاجة.", "يُقدّم دعمًا استباقيًا ومخصصًا لكل متعلم بناءً على احتياجاته الفردية، ويستخدم استراتيجيات متعددة لتحسين الأداء، ويُظهر تميزًا في تطبيق استراتيجيات تقويمية مبتكرة ومتنوعة تساهم في تحقيق نتائج استثنائية، ويعدّل الخطط بشكل فوري عند الحاجة."]}, {"no": 6, "title": "إعداد وتنفيذ خطة التعلم", "weight": 10, "text": "ويقصد بها تمكن المعلم من إعداد خطة منظمة تساعد على تحديد الأهداف التعليمية وتنفيذها بوضوح مما يحسن ويجود الأداء التدريسي. ويكون قادرًا على:", "bullets": ["إعداد خطة التعلم وفق السياسات المنظمة لذلك، وبما يواءم مع تشخيص واقع المتعلمين.", "تحقيق الأهداف التعليمية وعناصر المواد المسندة إليه.", "التخطيط للأنشطة الصفية والأنشطة غير الصفية من قبل المعلم الخبير (إن وجد).", "مشاركة المعلم الممارس والمعلم المتقدم في الإعداد والتنفيذ للأنشطة الصفية والأنشطة غير الصفية.", "تفهم الخصائص النفسية للمرحلة العمرية التي يقوم بتدريسها."], "levels": ["نادرًا ما يقوم بإعداد خطة التعلم ويعتمد بشكل كامل على التدريس المباشر دون إعداد مسبق.", "يقوم بإعداد خطة تعلم تتضمن أهداف تعليمية غير واضحة، ويعتمد على المواد الجاهزة دون تخصيص أو تطوير المحتوى ليتناسب مع المتعلمين. ويفتقر إلى التنويع في أساليب التدريس.", "يقوم بإعداد خطة تعلم تتضمن أهداف تعليمية واضحة ومحددة لا تراعي الفروق الفردية بين المتعلمين ولا تغطي المحتوى التعليمي، ويستخدم مواد تعليمية غير كافية ولا ينوع في استخدام أساليب التدريس.", "يقوم بإعداد خطة تعلم تتضمن أهداف تعليمية واضحة ومحددة وقابلة للقياس تراعي الفروق الفردية بين المتعلمين، وتلبي جميع احتياجاتهم بشكل فعال. وينظم الدرس بشكل منطقي ويخصص وقتًا كافيًا لكل نشاط ويراعي التنوع في أساليب التدريس.", "يقوم بإعداد خطة تعلم تتضمن أهداف تعليمية واضحة ومحددة وقابلة للقياس تراعي الفروق الفردية بين المتعلمين، ويكيفها وفق احتياجات جميع المتعلمين، ويستخدم أساليب تدريس مبتكرة ومتنوعة، مع مراعاة أساليب التعلم واستخدام مواد تعليمية تفاعلية لتعزيز فهم المتعلمين."]}, {"no": 7, "title": "توظيف تقنيات ووسائل التعلم المناسبة", "weight": 10, "text": "ويقصد بها قدرة المعلم على استخدام الوسائل التعليمية والأدوات المتنوعة المناسبة للموقف التعليمي لتحسين العملية التعليمية. ويكون قادرًا على:", "bullets": ["تنويع تقنيات ووسائل التعلم المناسبة بغرض تحقيق الأهداف التعليمية بفاعلية.", "مراعاة الفروق الفردية بين المتعلمين لتيسير نقل الخبرات التعليمية بسهولة ووضوح.", "استخدام التقنيات والوسائل التعليمية المناسبة لحاجات وأنماط المتعلمين.", "إكساب الطلبة المعرفة وتنمية قدراتهم على التأمل والملاحظة والتفكير العلمي للوصول إلى حل المشكلات."], "levels": ["نادرًا ما يستخدم التقنيات والوسائل التعليمية المناسبة.", "يستخدم التقنيات والوسائل التعليمية بشكل محدود ولا تتناسب مع المحتوى التعليمي.", "يستخدم أغلب التقنيات والوسائل التعليمية المناسبة ويوظفها بشكل منتظم وتتناسب مع المحتوى التعليمي.", "يستخدم جميع التقنيات والوسائل التعليمية المتوفرة بالمدرسة المناسبة ويوظفها بشكل منتظم وتتناسب مع احتياجات المتعلمين مما يعزز من فعالية الدروس.", "يستخدم جميع التقنيات والوسائل التعليمية المتوفرة بالمدرسة ويُظهر مهارة استثنائية في دمج التقنيات الحديثة بشكل سلس في الدروس، مع تحسين تفاعل المتعلمين واستيعابهم للمحتوى، يستخدم الأدوات التقنية بفعالية لتحفيز المتعلمين."]}, {"no": 8, "title": "تهيئة البيئة التعليمية", "weight": 5, "text": "ويقصد بها قدرة المعلم على ممارسة عمليات تتضمن المدخلات والعمليات والإجراءات اللازمة والتي توفر للمتعلمين على اختلاف قدراتهم وميولهم واهتماماتهم واحتياجاتهم التعليمية فرصًا متكافئة لفهم واستيعاب المفاهيم واستخدامها في مواقف الحياة اليومية. ويكون قادرًا على:", "bullets": ["توفير بيئة تعليمية آمنة تشجع على التعلم وتدعم النمو الشخصي والأكاديمي، وتشمل الأمان المادي للبيئة المحيطة.", "توفير مساحة تعليمية آمنة خالية من الأخطار المادية مثل معدات غير آمنة أو بنية تحتية متهالكة.", "توفير بيئة تعليمية تحقق الأمان النفسي وتتسم بالاحترام المتبادل.", "توفير بيئة تعليمية تمكن المتعلمين من التعبير عن أنفسهم ومشاركة أفكارهم مع أقرانهم.", "إثارة دافعية المتعلمين من خلال التنويع في أساليب التعلم."], "levels": ["نادرًا ما يخلق بيئة تعليمية محفزة أو داعمة للتعلم النشط.", "يبني بيئة تعليمية تعزز فهم الطلاب بشكل جزئي للمعرفة.", "يبني بيئة تعليمية تعزز فهم الطلاب للمعرفة وتراعي الفروق الفردية بين المتعلمين.", "يبني بيئة تعليمية معززة ومحفزة للتعليم والتعلم وفق احتياجات المتعلمين.", "يبني بيئة تعليمية آمنة معززة ومحفزة للتعليم، تستدعي خبرات المتعلمين، وتنمي مهاراتهم لتقديم معارف جديدة تستند على الدروس السابقة."]}, {"no": 9, "title": "الإدارة الصفية", "weight": 5, "text": "ويقصد بها جميع الخطوات والإجراءات اللازمة لتحقيق بيئة صفية آمنة وجاذبة وملائمة لعمليتي التعلم والتعليم تأخذ بعين الاعتبار الأبعاد النفسية والاجتماعية والعقلية والجسمية للمتعلم، مما يساعد على تحقيق الأهداف التعليمية المنشودة ويكون قادرًا على:", "bullets": ["مراعاة الفروق الفردية بين المتعلمين.", "توجيه المتعلمين لتطبيق القوانين والتعليمات الصفية.", "تعزيز الانضباط عند المتعلمين وتنظيم عملية التفاعل والتواصل بينهم.", "تنظيم الطلاب بما يناسب الموقف المدرسي."], "levels": ["نادرًا ما يدير الصف بفاعلية.", "يدير الصف دون مراعاة القوانين والتعليمات الصفية.", "يدير الصف بفاعلية ويظهر قدرة على توجيه المتعلمين لتطبيق القوانين والتعليمات الصفية.", "يدير الصف بفاعلية ويوفر بيئة صفية ممتعة، وإعطاء فرص متكافئة للطلاب للإجابة عن الأسئلة.", "يدير الصف بكفاءة عالية يبني علاقات إيجابية مع المتعلمين ويشجع التفاعل بين الأقران ويوفر بيئة صفية محفزة تستثير المعرفة، ويمتلك القدرة على التعامل مع الطلبة وفق احتياجاتهم."]}]}'::jsonb as f, (select p from pos) * 10 + 3 as k
  union all
  select '{"name": "rb_perf_admin", "type": "rubric", "label": "أعمال إدارية ومكتبية", "required": false, "style": "official", "note": "سيتم التقييم بعد الاطلاع على ملف إنجاز المعلم وملف الشواهد.", "items": [{"no": 1, "title": "أداء الواجبات الوظيفية", "weight": 5, "text": "يطبق الأنظمة وقواعد السلوك الوظيفية وأخلاقيات بيئة التعلم، كما يعزز الانتماء والولاء للوطن، والقيم الوطنية، ويحافظ على خصوصية المعلومات المهنية وحماية البيانات والمعلومات التي تتعلق بالعمل أو الأنشطة المهنية من الوصول غير المصرح به والامتثال للقوانين واللوائح وسياسات وإجراءات العمل التي تتوافق مع القوانين واللوائح المحلية والدولية.", "bullets": [], "levels": ["يُظهر الحد الأدنى للواجبات الوظيفية المطلوبة منه ويتأخر عن العمل بشكل مستمر ودون مبرر.", "يُظهر التزامًا محدودًا للواجبات الوظيفية ويحتاج إلى توجيه متكرر ويتأخر عن العمل أحيانًا دون سبب واضح.", "يُظهر التزامًا جيدًا للواجبات الوظيفية الأساسية ويؤديها ويُظهر استعدادًا لتحمل المسؤوليات الإضافية بشكل غير منتظم، ويلتزم بمواعيد العمل معظم الوقت.", "يلتزم بوضوح بالواجبات الوظيفية بشكل جيد ودون الحاجة إلى توجيه مستمر ويتحمل المهام الإضافية ويحرص على تحسين الأداء بشكل مستمر، ويلتزم بمواعيد العمل بشكل منتظم ولا يتأخر إلا لأسباب مبررة.", "يلتزم تمامًا ويُظهر احترافية عالية في أداء جميع الواجبات الوظيفية دون الحاجة إلى أي توجيه، ويُبادر بشكل استباقي إلى تحمل المسؤوليات الإضافية ويتولى المهام الأكثر تعقيدًا، ودائم الالتزام بمواعيد العمل، ويكون حاضرًا بشكل دائم قبل الوقت المطلوب."]}, {"no": 2, "title": "التفاعل مع المجتمع المهني", "weight": 5, "text": "المشاركة الفعالة في مجتمعات وشبكات التعليم تسهم في تبادل المعرفة وتطوير المهارات المهنية وتعزيز أفضل الممارسات التعليمية. يشمل ذلك:", "bullets": ["التعلم المستمر من خلال التطوير المهني وورش العمل، والدورات والمؤتمرات.", "الإسهام في التطوير: عبر الأبحاث، تطوير المناهج، ودعم السياسات التعليمية.", "التعاون والتواصل لبناء شبكات مهنية، تبادل الأفكار ومواجهة التحديات التعليمية.", "الإرشاد والتوجيه بدعم المعلمين الجدد ومشاركة الخبرات.", "التفكير الذاتي: لتحسين الممارسات وبناء بيئة تعليمية تعزز التعلم المستمر والتطوير."], "levels": ["يُظهر الحد الأدنى من الاهتمام والجهد للتفاعل مع المجتمع المهني.", "يتواجد في أنشطة المجتمع المهني دون المشاركة الفعالة.", "يشارك في بعض فعاليات وأنشطة المجتمع المهني، بشكل غير منتظم أو عندما يكون مطلوبًا منه.", "يشارك بانتظام في أنشطة وفعاليات المجتمع المهني ويُظهر تفاعلًا إيجابيًا مع الزملاء في مجال عمله.", "يشارك بشكل استباقي ودائم في جميع الفعاليات والأنشطة المهنية ذات الصلة ويشجع الآخرين على المشاركة والتفاعل المستمر ويُظهر استعدادًا للمساعدة."]}, {"no": 3, "title": "التفاعل مع أولياء الأمور", "weight": 5, "text": "المساهمة في دعم وتحقيق بيئة تعليمية فعالة لتحسين التحصيل الدراسي للطلبة وتعزيز تجربتهم لدعم التطور التعليمي والشخصي لهم، ويتضمن تفعيل قنوات اتصال فعالة مع أولياء الأمور لمناقشة تقدم الطلبة والتحديات التي قد تواجههم، وتشجيع أولياء الأمور على المشاركة في العملية التعليمية، مثل المساعدة في الواجبات المنزلية وتوفير بيئة داعمة، والتواصل المستمر مع أولياء الأمور باستخدام أساليب إيجابية لمناقشة التقدم العلمي والاجتماعي للمتعلمين وخطط التطوير المستقبلية للطلبة وإيجاد حلول مشتركة، والاستجابة والاستماع إلى مخاوف أولياء الأمور والعمل بشكل تعاوني لمعالجتها.", "bullets": [], "levels": ["نادرًا ما يشارك في أي نوع من التواصل مع أولياء الأمور.", "يشارك في التواصل مع أولياء الأمور بشكل محدود عند الطلب، ويُقدم معلومات غير كافية حول أداء المتعلمين.", "يشارك في التواصل مع أولياء الأمور عند الحاجة، يقدم معلومات كافية حول أداء المتعلمين.", "يتواصل بانتظام مع أولياء الأمور، ويقدم معلومات كافية ومفيدة حول احتياجات وأداء المتعلمين ويستجيب لأسئلتهم ومخاوفهم بسرعة وفعالية.", "يبادر بالتواصل الدائم الفعال مع أولياء الأمور، ويقدم معلومات دقيقة وشاملة عن احتياجات وأداء المتعلمين تساهم بشكل استباقي في التطوير والتحسين."]}, {"no": 10, "title": "تحليل نتائج المتعلمين وتشخيص مستوياتهم", "weight": 10, "text": "تحليل البيانات لتطوير التعلم عملية تستخلص الحقائق والاستنتاجات من البيانات لتقييم أداء المتعلمين بوضوح وتقديم تغذية راجعة بناءة. تشمل:", "bullets": ["تنويع مصادر التقييم لضمان شمولية النتائج وتقليل التحيز.", "تطوير أهداف تعليمية قصيرة وطويلة المدى تراعي الفروق الفردية وبيئة التعلم.", "تفسير البيانات: لاتخاذ قرارات مستنيرة بشأن فعالية التدريس والمناهج.", "قياس التطبيق العملي للمعرفة عبر مواقف ومشاريع حقيقية.", "تحليل الأداء العام لتحديد نقاط القوة والضعف، مع إشراك المتعلمين في فهم نتائجهم وتقديم ملاحظات تدعم التطور المستمر."], "levels": ["نادرًا ما يقوم بتحليل نتائج المتعلمين بشكل منهجي.", "يُجري تحليلًا محدودًا للنتائج، ولكن دون الاعتماد على أدوات أو أساليب دقيقة.", "يُجري تحليلًا أساسيًا لنتائج المتعلمين باستخدام بعض الأدوات أو الأساليب المتاحة.", "يُجري تحليلًا دقيقًا وشاملًا لنتائج المتعلمين باستخدام أدوات وأساليب منهجية، ويقدم تشخيصًا دقيقًا لاحتياجات كل متعلم بناءً على بيانات تحليلية واضحة، ويقدم توصيات مخصصة لتحسين أداء المتعلمين.", "يُجري تحليلًا متقدمًا لنتائج المتعلمين باستخدام تقنيات تحليل البيانات المتقدمة لتحديد التوجهات الفردية والجماعية، يقدم تشخيصًا دقيقًا وشاملًا لمستويات المتعلمين ويستخدم التحليل لتقديم خطط تطوير فردية مخصصة، ويعمل على تحسين مستمر لأساليب تحليل النتائج."]}, {"no": 11, "title": "تنوع أساليب التقويم", "weight": 10, "text": "ويقصد بها استخدام مجموعة متنوعة من الطرق وتتوافق مع أهداف التعلم مع التأكد من أن الأدوات والنماذج والتي تتسم بأنها واضحة ومحددة وصادقة وموثوقة وتقيّم ما هو مقصود بها، لتقييم التقدم والإنجازات الأكاديمية للمتعلمين خلال فترة زمنية محددة ويكون قادرًا على:", "bullets": ["معرفة وفهم أساليب وأدوات التقويم المتنوعة.", "معرفة وفهم خصائص نمو المتعلمين وأساليب تعلمهم.", "استخدام مصادر متنوعة للتقييم مثل الملاحظة الصفية، الاستبانات، التقارير الذاتية، تحليل نتائج المتعلمين.", "توظيف أساليب تقويم متنوعة على أن يكون من ضمنها الاختبارات (شفهية، تحريرية) والمهمات الأدائية التي تتناسب مع طبيعة الأهداف ومخرجات التعلم.", "مراعاة الفروق الفردية بين المتعلمين أثناء التقويم وتقديم التغذية الراجعة لرفع مستوى التحصيل الدراسي.", "الاستفادة من نتائج تنوع أساليب وأدوات التقويم بتوظيفها في تحسين مستوى الأداء بصفة مستمرة.", "استخدام التقويم القبلي (التشخيصي) للوقوف على مدى استعداد المتعلمين وتشخيص امتلاكهم لمهارات وخبرات أساسية سابقة.", "تطبيق التقويم التكويني أثناء عملية التعلم لبناء وتطوير المهارات والكفايات لدى المتعلمين وإصدار أحكام عن مستوياتهم وفق معايير كمية ونوعية يقاس من خلالها التعلم.", "تطبيق التقويم الختامي لمعرفة مدى تحقق أهداف العملية التعليمية وقياس تقدم التعلم وإصدار أحكام عن مستويات الطلبة."], "levels": ["نادرًا ما يستخدم أساليب وأدوات تقييم مناسبة.", "يعتمد فقط على نوع واحد من أساليب التقييم، لكنه قد لا يكون شاملًا بشكل كافٍ.", "يستخدم أساليب وأدوات تقييم مناسبة تقوم على أسس علمية، ويُوظف مجموعة من أساليب التقييم متوافقة مع طبيعة الأهداف ومخرجات التعلم.", "يستخدم أساليب وأدوات تقييم مناسبة تقوم على أسس علمية لرفع مستوى التحصيل الدراسي ويستخدم مجموعة متنوعة من أساليب التقويم.", "يستخدم أساليب وأدوات تقييم مناسبة لرفع مستوى التحصيل وتوظيفها في تحسين عملية التعليم، استخدام أساليب تقييم تساعد على قياس مدى تحقق أهداف العملية التعليمية وقياس تقدم التعلم وإصدار أحكام عن مستويات الطلبة."]}]}'::jsonb, (select p from pos) * 10 + 4
),
allx as (
  select f, o * 10 as k from els
  union all
  select f, k from added
)
update public.form_templates
set fields = (select jsonb_agg(f order by k) from allx),
    updated_at = now()
where id = '767d1060-fb69-4888-8e64-32d787802bd5';

-- للتحقق: الجدولان الجديدان بعد «تاريخ الزيارة»، والقديمان legacy
select f->>'name' as name, f->>'label' as label, f->>'type' as type, coalesce(f->>'legacy', '') as legacy,
       jsonb_array_length(coalesce(f->'items', '[]'::jsonb)) as items
from public.form_templates, jsonb_array_elements(fields) f
where id = '767d1060-fb69-4888-8e64-32d787802bd5';
